const S = [
 {id:'dagon',t:'Dagon',y:1917,p:`A merchant sailor escapes a German raider, drifts onto a vast plain of upheaved sea-bottom, and watches a colossal scaled being embrace a carved monolith. Morphine-ridden, he finishes his account as something reaches his door.`},
 {id:'polaris',t:'Polaris',y:1918,p:`A dreamer becomes a sentry of Olathoë in ancient Lomar, falls asleep at his post as the Inutos come, and is now trapped in a waking world he insists is the dream.`},
 {id:'statement',t:'The Statement of Randolph Carter',y:1919,p:`Harley Warren goes down into an ancient tomb in Big Cypress Swamp with a lantern and a telephone line. Carter waits above. The last voice on the line is not Warren's.`},
 {id:'sarnath',t:'The Doom That Came to Sarnath',y:1919,p:`The men of Sarnath slaughter the beings of Ib and steal the idol of their god Bokrug. A thousand years later, Sarnath vanishes in a single night.`},
 {id:'jermyn',t:'Facts Concerning the Late Arthur Jermyn and His Family',y:1920,p:`Arthur Jermyn learns what his explorer ancestor really married in the Congo, and sets himself on fire.`},
 {id:'ulthar',t:'The Cats of Ulthar',y:1920,p:`An old couple who torture cats vanish after the boy Menes prays; their skeletons are found picked clean, and Ulthar passes its law.`},
 {id:'celephais',t:'Celephaïs',y:1920,p:`Kuranes, a dreamer in London, finds the city of his childhood dreams again, dies a tramp's death in the waking world, and becomes its king for ever.`},
 {id:'nyarl',t:'Nyarlathotep',y:1920,p:`A dark showman comes out of Egypt and tours the cities with electrical wonders. Behind him, civilisation dissolves into nightmare.`},
 {id:'othergods',t:'The Other Gods',y:1921,p:`Barzai the Wise climbs Hatheg-Kla to see the gods of Earth dance, meets the Other Gods instead, and falls screaming into the sky. His disciple Atal comes down alone.`},
 {id:'zann',t:'The Music of Erich Zann',y:1921,p:`A student on the Rue d'Auseil hears the mute violist Erich Zann playing frantic music at his high window, holding back what lies beyond it.`},
 {id:'nameless',t:'The Nameless City',y:1921,p:`An explorer crawls into a forgotten city in the Arabian desert, built for a reptilian race, and learns what Alhazred's couplet means.`},
 {id:'outsider',t:'The Outsider',y:1921,p:`A lonely being climbs out of a lightless castle into a ballroom, sees the guests flee, and touches the monster in the gilded frame.`},
 {id:'west',t:'Herbert West—Reanimator',y:1922,p:`A medical student reanimates corpses from Arkham to Flanders until his creations come back for him.`},
 {id:'hound',t:'The Hound',y:1922,p:`Two grave-robbers steal a jade amulet from a Dutch grave and are hunted by distant baying. The Necronomicon is named for the first time.`},
 {id:'rats',t:'The Rats in the Walls',y:1923,p:`Delapore restores Exham Priory, follows the scurrying in the walls down into a vast grotto, and regresses into his ancestors.`},
 {id:'unnamable',t:'The Unnamable',y:1923,p:`In an Arkham burying-ground, Randolph Carter argues with Joel Manton about whether anything can be "unnamable," until something answers.`},
 {id:'festival',t:'The Festival',y:1923,p:`A man comes to ancient Kingsport for the Yuletide rite of his forebears and descends beneath the church to an oily underground river and the winged things that bear the worshippers away.`},
 {id:'coc',t:'The Call of Cthulhu',y:1926,p:`Francis Thurston assembles his late great-uncle's notes on a dream-sculpture, a Louisiana swamp cult and a sailor's account of the risen city of R'lyeh.`},
 {id:'pickman',t:"Pickman's Model",y:1926,p:`Thurber explains why he dropped the painter Richard Upton Pickman, and what was in the photograph pinned to the canvas.`},
 {id:'silverkey',t:'The Silver Key',y:1926,p:`At fifty, disenchanted Randolph Carter finds an ancestral silver key, returns to his boyhood near Arkham, and vanishes from the waking world.`},
 {id:'strangehouse',t:'The Strange High House in the Mist',y:1926,p:`Philosopher Thomas Olney climbs to the house on Kingsport's highest cliff and comes down with his soul left behind. Nodens passes overhead.`},
 {id:'kadath',t:'The Dream-Quest of Unknown Kadath',y:1927,p:`Randolph Carter crosses the Dreamlands in search of the sunset city the gods have denied him, from Ulthar to the Moon, the underworld, Leng and Kadath itself.`},
 {id:'cdw',t:'The Case of Charles Dexter Ward',y:1927,p:`A young antiquarian raises his wizard ancestor Joseph Curwen, who murders and replaces him. The family doctor goes down into the catacombs.`},
 {id:'colour',t:'The Colour Out of Space',y:1927,p:`A meteorite falls on Nahum Gardner's farm west of Arkham, and something inside it slowly drains the land and the family to grey dust.`},
 {id:'yig',t:'The Curse of Yig',y:1928,rev:'with Zealia Bishop',p:`In 1889 Oklahoma, Walker Davis kills a nest of rattlesnakes. His wife Audrey waits in the dark for the snake-god's revenge.`},
 {id:'dunwich',t:'The Dunwich Horror',y:1928,p:`Wilbur Whateley, son of an unnamed father, dies stealing the Necronomicon, and his invisible twin breaks loose across the Dunwich hills.`},
 {id:'mound',t:'The Mound',y:1930,rev:'with Zealia Bishop',p:`An Oklahoma mound hides the manuscript of Zamacona, a Spanish conquistador who entered the blue-lit underground world of K'n-yan.`},
 {id:'whisperer',t:'The Whisperer in Darkness',y:1930,p:`Folklorist Albert Wilmarth corresponds with Henry Akeley about winged things in the Vermont hills, then visits him.`},
 {id:'mountains',t:'At the Mountains of Madness',y:1931,p:`Geologist William Dyer explains why no one should follow the Miskatonic expedition to Antarctica: the city beyond the mountains, and what still lives under it.`},
 {id:'innsmouth',t:'The Shadow over Innsmouth',y:1931,p:`A young traveller passes through the decayed port of Innsmouth, escapes its hybrids by night, and finds out whose blood he carries.`},
 {id:'witch',t:'The Dreams in the Witch House',y:1932,p:`Mathematics student Walter Gilman rents Keziah Mason's old garret and dreams through its angles into other dimensions as Walpurgis Night approaches.`},
 {id:'museum',t:'The Horror in the Museum',y:1932,rev:'with Hazel Heald',p:`Stephen Jones bets he can spend a night in George Rogers's waxworks, where Rogers keeps the god he brought back from Alaska.`},
 {id:'gate',t:'Through the Gates of the Silver Key',y:1933,rev:'with E. Hoffmann Price',p:`Carter's heirs meet in New Orleans to divide his estate, and a veiled swami explains what lay beyond the Ultimate Gate.`},
 {id:'aeons',t:'Out of the Aeons',y:1933,rev:'with Hazel Heald',p:`A mummy in Boston's Cabot Museum, and the scroll found with it, tell of T'yog of Mu, who climbed Yaddith-Gho to defy Ghatanothoa.`},
 {id:'doorstep',t:'The Thing on the Doorstep',y:1933,p:`Daniel Upton explains why he put six bullets into the head of his best friend, Edward Derby.`},
 {id:'shadowtime',t:'The Shadow Out of Time',y:1935,p:`Professor Nathaniel Peaslee loses five years to amnesia, then finds proof in the Australian desert that his mind was elsewhere.`},
 {id:'haunter',t:'The Haunter of the Dark',y:1935,p:`Writer Robert Blake explores an abandoned church on Federal Hill, finds the Shining Trapezohedron, and wakes what it summons.`},
];

/* ---------- Entries ---------- */
const E = [
/* Other Gods */
{id:'azathoth',n:'Azathoth',c:'og',ep:'The daemon sultan at the centre of infinity',s:['kadath','whisperer','witch','haunter'],l:['nyarlathotep','keziah','gilman','blake','kadath','shantaks'],
 d:`Lovecraft's supreme power is mindless. Azathoth sprawls at the centre of Ultimate Chaos, gnawing hungrily beyond time, while lesser Other Gods dance around it to the thin, monotonous piping of flutes. It doesn't scheme; Nyarlathotep acts as its soul and messenger. Keziah Mason means to bring Walter Gilman to its throne to sign the book in his own blood.`,
 q:`the boundless daemon sultan Azathoth, whose name no lips dare speak aloud`,qs:'kadath'},
{id:'yogsothoth',n:'Yog-Sothoth',c:'og',ep:'The Key and the Gate',s:['cdw','dunwich','whisperer','haunter','museum','gate'],l:['wilbur','twin','lavinia','oldwhateley','curwen','ward','carter','umr','necronomicon','sentinelhill','rogers','silverkey'],
 d:`Yog-Sothoth touches every point of time and space at once, which is why sorcerers want it: whoever has its favour can pass anywhere and anywhen. Joseph Curwen's formulae call on it, and Lavinia Whateley bore it twin sons on Candlemas 1913. George Rogers's waxwork shows it as a congeries of iridescent globes. Beyond the Ultimate Gate, Randolph Carter meets it as the All-in-One.`,
 q:`Yog-Sothoth knows the gate. Yog-Sothoth is the gate. Yog-Sothoth is the key and guardian of the gate.`,qs:'dunwich'},
{id:'nyarlathotep',n:'Nyarlathotep',c:'og',ep:'The Crawling Chaos',s:['nyarl','kadath','whisperer','witch','haunter'],l:['azathoth','carter','blake','trapezohedron','starrywisdom','gilman','keziah','migo','greatones','kadath','akeley','shantaks'],
 d:`The only Other God who walks among people, and the one who seems to enjoy it. In the 1920 prose poem he arrives from Egypt as a swarthy showman of electrical marvels, and the world unravels behind his tour. He is the tall, smiling pharaoh who toys with Randolph Carter on Kadath, the Black Man of the Arkham witch-cult, the Mighty Messenger of the Mi-Go, and the winged thing the Shining Trapezohedron calls down on Robert Blake.`,
 q:`And it was then that Nyarlathotep came out of Egypt.`,qs:'nyarl'},
{id:'shub',n:'Shub-Niggurath',c:'og',ep:'The Black Goat of the Woods with a Thousand Young',s:['dunwich','whisperer','mound','aeons'],l:['migo','akeley','wilmarth','tyog','kenyan','oldwhateley'],
 d:`Lovecraft never shows Shub-Niggurath, but its name runs through the chants: the Vermont phonograph record, the Dunwich rites, the temples of K'n-yan. In "Out of the Aeons" the priest T'yog serves it on Mu and draws on its help against Ghatanothoa. Its title suggests a monstrous fertility, a mother of endless young.`,
 q:`Iä! Shub-Niggurath! The Black Goat of the Woods with a Thousand Young!`,qs:'whisperer'},

/* Great Old Ones & deities */
{id:'cthulhu',n:'Cthulhu',c:'gd',ep:"Dead but dreaming in R'lyeh",s:['coc','innsmouth','whisperer','mountains','mound'],l:['rlyeh','thurston','angell','legrasse','johansen','wilcox','castro','cthulhucult','starspawn','deepones','dagon','necronomicon','kenyan'],
 d:`Mountainous, with an octopus's head, a scaly body and rudimentary wings, the high priest of the Great Old Ones lies dead but dreaming in sunken R'lyeh until the stars come right. His dreams leak into sensitive minds. In the spring of 1925 R'lyeh rose and he emerged; Gustaf Johansen drove the steam yacht Alert straight through him, the mass recombined, and the city sank again. K'n-yan worships him as Tulu. The chant translates: "In his house at R'lyeh dead Cthulhu waits dreaming."`,
 q:`Ph'nglui mglw'nafh Cthulhu R'lyeh wgah'nagl fhtagn.`,qs:'coc'},
{id:'dagon',n:'Dagon',c:'gd',ep:'Father Dagon',s:['dagon','innsmouth'],l:['hydra','deepones','eod','obed','innsmouth','yhanthlei','cthulhu'],
 d:`In "Dagon" a sailor adrift on a newly risen plain of sea-bottom watches a gigantic scaled creature come out of the water and fling its arms around a carved monolith. In "The Shadow over Innsmouth" Father Dagon is the god of the Deep Ones, worshipped with Mother Hydra by the Esoteric Order of Dagon.`,
 q:`The end is near. I hear a noise at the door, as of some immense slippery body lumbering against it.`,qs:'dagon'},
{id:'hydra',n:'Mother Hydra',c:'gd',ep:'Consort of Dagon',s:['innsmouth'],l:['dagon','deepones','eod','zadok'],
 d:`Named in Zadok Allen's ravings and in the oaths of the Esoteric Order, Mother Hydra stands beside Father Dagon at the head of the Deep Ones. Lovecraft never describes her.`},
{id:'tsathoggua',n:'Tsathoggua',c:'gd',ep:'Borrowed from Clark Ashton Smith',s:['whisperer','mound'],l:['kenyan','zamacona','wilmarth','akeley','eibon'],
 d:`Smith created this sleepy, toad-like god, and Lovecraft wrote him into his own fiction. Wilmarth recognises the name in Akeley's letters. In "The Mound", K'n-yan once worshipped Tsathoggua, until explorers went down into black N'kai beneath their world and found his images tended by living, formless black things. They abandoned the cult.`},
{id:'yig',n:'Yig',c:'gd',ep:'Father of Serpents',s:['yig','mound'],l:['kenyan','zamacona'],
 d:`A snake-god of the southern Plains who avenges harm done to his children. In 1889 Walker Davis killed a nest of rattlesnakes; his wife Audrey, sure the curse was coming, took an axe to the shape she saw in the dark, and it was her husband. What she bore afterwards is still kept at the asylum. In "The Mound" Yig is one of K'n-yan's chief gods.`},
{id:'ghatanothoa',n:'Ghatanothoa',c:'gd',ep:'The god of Yaddith-Gho',s:['aeons'],l:['tyog','migo','yuggoth','shub'],
 d:`The fungous beings from Yuggoth brought Ghatanothoa to Earth, and it lairs in the fortress beneath Mount Yaddith-Gho on Mu. Seeing it, or even a faithful image of it, turns the viewer to leathery stone with the brain still alive inside. T'yog climbed the mountain with a scroll to defeat it, but its priests had swapped the scroll.`},
{id:'rhantegoth',n:'Rhan-Tegoth',c:'gd',ep:'The god in the waxworks',s:['museum'],l:['rogers','yuggoth'],
 d:`George Rogers claimed to have found this god dormant on an ivory throne in Arctic ruins in Alaska. It has a globular body, six long limbs ending in crab-like claws, and a head with a sucking proboscis. It came from Yuggoth three million years ago, and Rogers fed it.`},
{id:'bokrug',n:'Bokrug',c:'gd',ep:'The great water-lizard',s:['sarnath'],l:['sarnath'],
 d:`The god of the silent green beings of Ib, in the land of Mnar. When the men of Sarnath massacred them, they carried off his sea-green stone idol as a trophy. A thousand years later, at the feast celebrating the destruction of Ib, Sarnath was wiped out in a night. Only the idol remained.`},
{id:'nodens',n:'Nodens',c:'gd',ep:'Lord of the Great Abyss',s:['strangehouse','kadath'],l:['nightgaunts','carter','kingsport'],
 d:`A hoary, archaic god of the deep who rides a great shell through the sky above Kingsport. He is one of the few powers in Lovecraft that helps people: the night-gaunts serve him, and in the Dream-Quest they carry Randolph Carter out of danger.`},
{id:'greatones',n:'The Great Ones',c:'gd',ep:'The gods of Earth',s:['othergods','kadath'],l:['kadath','barzai','atal','nyarlathotep','carter'],
 d:`The mild gods of Earth have withdrawn to an onyx castle on unknown Kadath and dance on the peaks on moonlit nights. They are weak, and the Other Gods and Nyarlathotep protect them. Barzai climbed Hatheg-Kla to see them and was taken by the Other Gods; Carter crosses the Dreamlands to petition them.`},
{id:'umr',n:"'Umr at-Tawil",c:'gd',ep:'The Most Ancient One',s:['gate'],l:['yogsothoth','carter','silverkey','necronomicon'],
 d:`The veiled guide at the Ultimate Gate. He receives Randolph Carter beyond the first gateway and leads him past the Ancient Ones on their pedestals toward Yog-Sothoth. The Necronomicon renders his name as "the Prolonged of Life."`},

/* Beings & races */
{id:'elderthings',n:'Elder Things',c:'br',ep:'The Old Ones of Antarctica',s:['mountains','witch'],l:['shoggoths','dyer','danforth','lake','antarctic','starspawn','migo','gilman'],
 d:`Barrel-bodied, eight feet long, with folding membranous wings, a five-pointed starfish head and five-part symmetry throughout. They came to the young Earth from space, built a titanic city on the Antarctic plateau, and may have created terrestrial life by accident. They fought Cthulhu's spawn and the Mi-Go. Lake's expedition dug up specimens that were not dead. Walter Gilman brings one of their images back from a dream.`,
 q:`Radiates, vegetables, monstrosities, star-spawn—whatever they had been, they were men!`,qs:'mountains'},
{id:'shoggoths',n:'Shoggoths',c:'br',ep:'Servants of the Elder Things',s:['mountains','doorstep'],l:['elderthings','dyer','danforth','antarctic','derby'],
 d:`Fifteen-foot masses of black, iridescent protoplasm that the Elder Things bred as living tools, shaping new organs by hypnotic command. Over the ages they grew minds of their own, learned to mimic their masters' piping speech, and rebelled. Dyer and Danforth flee one through the tunnels beneath the city as it comes on like a subway train. Edward Derby raves about the pit of the shoggoths.`,
 q:`Tekeli-li! Tekeli-li!`,qs:'mountains'},
{id:'migo',n:'Mi-Go',c:'br',ep:'The Fungi from Yuggoth',s:['whisperer','mountains'],l:['yuggoth','akeley','wilmarth','nyarlathotep','shub','elderthings','ghatanothoa'],
 d:`Pinkish five-foot beings, part crustacean and part fungus, with several pairs of limbs, membranous wings that beat through the ether, and a convoluted head that changes colour as they communicate. From their outpost on Yuggoth they mine the Vermont hills, imitate human voices with a buzzing drone, and take living human brains to the stars in metal cylinders. The Himalayan legends of the Mi-Go are about them.`},
{id:'yith',n:'Great Race of Yith',c:'br',ep:'Minds that travel through time',s:['shadowtime'],l:['peaslee','polyps','yithcity','pnakotic'],
 d:`Minds that fled their dying world Yith and took over ten-foot, cone-shaped bodies on Earth some 150 million years ago. They swap minds with beings throughout time to study them, while the displaced mind lives in a cone body and writes its history for their archive. Before the polyps destroyed them, their minds fled again, into a beetle-like race that will follow mankind.`},
{id:'polyps',n:'Flying Polyps',c:'br',ep:'The elder enemies of the Great Race',s:['shadowtime'],l:['yith','peaslee','yithcity'],
 d:`Half-material beings, partly invisible, that moved without wings and struck with blasts of wind, announced by a peculiar whistling. The Great Race drove them into basalt cities underground and sealed the trapdoors. The polyps broke out. Peaslee finds one of those trapdoors open.`},
{id:'deepones',n:'Deep Ones',c:'br',ep:'Children of Dagon',s:['innsmouth'],l:['dagon','hydra','cthulhu','obed','zadok','olmstead','yhanthlei','innsmouth','eod','asenath'],
 d:`Grey-green amphibians with pale bellies, gills, bulging unblinking eyes and croaking voices. They live in cities under the sea, cannot die except by violence, and breed with humans; the offspring slowly develop the "Innsmouth look" and go down to the water for good. Obed Marsh's bargain gave Innsmouth fish and gold in exchange for its people.`},
{id:'starspawn',n:'Star-spawn of Cthulhu',c:'br',ep:"Builders of R'lyeh",s:['coc','mountains'],l:['cthulhu','rlyeh','elderthings'],
 d:`The octopoid race that came down from the stars with Cthulhu. Dyer reads their deep history in the Elder Things' carvings: they fought the Old Ones and held the Pacific lands, until R'lyeh sank and sealed them in.`},
{id:'colour',n:'The Colour Out of Space',c:'br',ep:'A hue outside the spectrum',s:['colour'],l:['nahum','ammi','blastedheath','miskatonic'],
 d:`In June 1882 a meteorite fell beside Nahum Gardner's well. It shrank away under the Miskatonic professors' tests and held a globule of a colour that belonged to no known part of the spectrum. Something settled in the well. Crops swelled and turned bitter, animals and people crumbled into grey dust, and part of it shot back into the sky. The rest stayed.`,
 q:`It was just a colour out of space—a frightful messenger from unformed realms of infinity beyond all Nature as we know it.`,qs:'colour'},
{id:'twin',n:"Wilbur's Twin",c:'br',ep:'The Dunwich Horror',s:['dunwich'],l:['wilbur','yogsothoth','armitage','sentinelhill','dunwich','lavinia','oldwhateley'],
 d:`Raised unseen in the boarded-up Whateley farmhouse and fed on cattle, it outgrew the house. After Wilbur died it broke loose, flattening farms and leaving prints the size of barrel-heads. Armitage's powder made it visible on Sentinel Hill: a heaving mass of ropy tentacles, bigger than a barn, with a half-face like Wilbur's at the top. It screamed for its father before it went.`,
 q:`HELP! HELP! ...ff—ff—ff—FATHER! FATHER! YOG-SOTHOTH!`,qs:'dunwich'},
{id:'brownjenkin',n:'Brown Jenkin',c:'br',ep:"Keziah Mason's familiar",s:['witch'],l:['keziah','gilman','arkham'],
 d:`A rat-sized furry thing with sharp teeth, a bearded, evil human face and tiny human hands. It carried messages between Keziah and the Devil and nursed on the witch's blood. It finished Walter Gilman by eating its way out of his chest.`},
{id:'kenyan',n:"People of K'n-yan",c:'br',ep:'The realm beneath Oklahoma',s:['mound'],l:['zamacona','tsathoggua','yig','shub','cthulhu'],
 d:`An ancient, telepathic people in a blue-lit cavern world under Oklahoma. They can dematerialise at will, have all but conquered death, and have sunk into idle cruelty, served by slaves and by the half-human gyaa-yothn. They worship Tulu and Yig. The conquistador Zamacona lived among them and tried to escape.`},

/* Dreamlands */
{id:'ghouls',n:'Ghouls',c:'dl',ep:'Feeders in the dark',s:['pickman','outsider','kadath'],l:['pickman','carter','nightgaunts','gugs','ghasts','outsider','moonbeasts'],
 d:`Rubbery, dog-faced, half-hoofed corpse-eaters who burrow beneath graveyards in the waking world and the dream underworld. Some were once human: Richard Upton Pickman painted them and later joined them. In the Dream-Quest they are Carter's allies, and their army storms the moon-beasts' rock.`},
{id:'nightgaunts',n:'Night-gaunts',c:'dl',ep:'Faceless servants of Nodens',s:['kadath'],l:['nodens','ghouls','carter','shantaks'],
 d:`Black, slick, faceless things with inward-curving horns, barbed tails and silent bat wings. They don't bite; they seize, tickle and carry their victims off. They serve Nodens and keep a pact with the ghouls, who lend them to Carter. Lovecraft dreamed of them as a child.`},
{id:'gugs',n:'Gugs',c:'dl',ep:'Giants of the underworld',s:['kadath'],l:['ghouls','ghasts','carter'],
 d:`Twenty-foot hairy giants whose mouths open vertically and whose arms each split into two forearms at the elbow. The Great Ones banished them underground for their abominable rites. The ghouls feud with them, and Carter creeps past their sleeping city.`},
{id:'ghasts',n:'Ghasts',c:'dl',ep:'Hoppers of the vaults of Zin',s:['kadath'],l:['gugs','ghouls'],
 d:`Kangaroo-hopping things with faces disturbingly close to human but without noses. Strong light kills them. They hunt gugs in the vaults of Zin.`},
{id:'moonbeasts',n:'Moon-beasts',c:'dl',ep:'The pale toads of the Moon',s:['kadath'],l:['lengmen','cats','carter','ghouls'],
 d:`Great greyish-white toadlike things that can stretch their shape, with a mass of short pink tentacles on their snouts. They sail black galleys to the dream ports, trading rubies for slaves, served by the men of Leng. They capture Carter and are routed by the cats of Ulthar.`},
{id:'lengmen',n:'Men of Leng',c:'dl',ep:'The horned merchants',s:['kadath'],l:['moonbeasts','leng','carter'],
 d:`Almost-men with wide mouths, small horns and hooves, who hide under turbans and shoes to trade in the Dreamlands' harbours. They live in stone villages on the plateau of Leng and are slaves of the moon-beasts.`},
{id:'zoogs',n:'Zoogs',c:'dl',ep:'Whisperers of the Enchanted Wood',s:['kadath'],l:['cats','carter'],
 d:`Small, brown, furtive creatures that live in burrows in the Enchanted Wood and know many secrets of the dream-world. They love moon-tree wine and plot against the cats of Ulthar, which catch them at it.`},
{id:'shantaks',n:'Shantaks',c:'dl',ep:'The horse-headed birds',s:['kadath'],l:['nightgaunts','nyarlathotep','carter','leng'],
 d:`Birds bigger than elephants, with horse-like heads and slippery scales instead of feathers, which nest near Leng. They fear only the night-gaunts. Nyarlathotep sends Carter off on one, toward Azathoth.`},
{id:'cats',n:'The Cats of Ulthar',c:'dl',ep:"Lovecraft's heroes",s:['ulthar','kadath'],l:['ulthar','carter','zoogs','moonbeasts','atal'],
 d:`No one in Ulthar may kill a cat, ever since an old couple who murdered them were found picked to the bone after the boy Menes prayed. In the Dream-Quest Carter can speak with cats; they save him from the zoogs and cross to the far side of the Moon to rescue him from the moon-beasts. Lovecraft adored cats.`,
 q:`It is said that in Ulthar, which lies beyond the river Skai, no man may kill a cat.`,qs:'ulthar'},

/* People */
{id:'thurston',n:'Francis Wayland Thurston',c:'pp',ep:'Narrator of The Call of Cthulhu',s:['coc'],l:['angell','legrasse','johansen','wilcox','cthulhu'],
 d:`A Bostonian who inherits his great-uncle George Angell's papers and pieces together the dream-sculpture, the Louisiana cult and Johansen's account. By the end he expects to die for what he knows.`,
 q:`The most merciful thing in the world, I think, is the inability of the human mind to correlate all its contents.`,qs:'coc'},
{id:'angell',n:'George Gammell Angell',c:'pp',ep:'Collector of the Cthulhu notes',s:['coc'],l:['thurston','wilcox','legrasse','cthulhu','cthulhucult'],
 d:`Professor emeritus of Semitic languages at Brown University. He heard Legrasse's story in 1908, gathered reports of the 1925 dream-wave and interviewed Wilcox. In 1926 he collapsed after a sailor jostled him on the Providence waterfront, and Thurston suspects he was killed.`},
{id:'legrasse',n:'John Raymond Legrasse',c:'pp',ep:'Raider of the swamp cult',s:['coc'],l:['castro','cthulhucult','angell','thurston','cthulhu'],
 d:`A New Orleans police inspector who led the 1907 raid on a cult ritual in the Louisiana swamps and seized its greenish-black idol. He brought it to the 1908 meeting of the American Archaeological Society to find out what it was.`},
{id:'johansen',n:'Gustaf Johansen',c:'pp',ep:'The man who rammed Cthulhu',s:['coc'],l:['cthulhu','rlyeh','thurston','cthulhucult'],
 d:`A Norwegian second mate whose schooner Emma was attacked by the cultist crew of the Alert in 1925. The survivors took the yacht and landed on risen R'lyeh, where Cthulhu emerged. Johansen steered straight through the god, came home to Oslo, wrote his account and soon died.`},
{id:'wilcox',n:'Henry Anthony Wilcox',c:'pp',ep:'The dreaming sculptor',s:['coc'],l:['angell','cthulhu'],
 d:`A young sculptor who brought Angell a bas-relief he had modelled from a dream on 1 March 1925, and repeated the words "Cthulhu fhtagn." He lay in fever through the weeks R'lyeh stood above the waves, and woke remembering nothing once it sank.`},
{id:'castro',n:'Old Castro',c:'pp',ep:'The cultist who talked',s:['coc'],l:['cthulhucult','legrasse','cthulhu'],
 d:`A very old prisoner from Legrasse's raid who claimed to have met the cult's deathless leaders in the mountains of China. Nearly everything known about the Great Old Ones and their return comes from his testimony.`},
{id:'carter',n:'Randolph Carter',c:'pp',ep:'The dreamer',s:['statement','unnamable','silverkey','kadath','gate'],l:['warren','kuranes','pickman','atal','nyarlathotep','greatones','umr','silverkey','cats','ghouls','nightgaunts','kadath','yogsothoth','arkham'],
 d:`Lovecraft's recurring dreamer and his closest alter ego. He waited above Harley Warren's tomb, argued about the unnamable in an Arkham burying-ground, crossed the Dreamlands to Kadath, and in 1928 disappeared with his silver key. Through the Gates reveals where he went.`},
{id:'warren',n:'Harley Warren',c:'pp',ep:'The man in the tomb',s:['statement'],l:['carter'],
 d:`Carter's friend and fellow occultist, who carried a book in an unknown alphabet. He went down into an ancient tomb in Big Cypress Swamp with a lantern and a telephone wire while Carter stayed above.`,
 q:`YOU FOOL, WARREN IS DEAD!`,qs:'statement'},
{id:'west',n:'Herbert West',c:'pp',ep:'Reanimator',s:['west'],l:['miskatonic','arkham'],
 d:`A slight, blond, spectacled Miskatonic medical student who believed life was a chemical process that could be restarted. He tried it on ever fresher corpses, from Arkham to Bolton to the trenches of Flanders. His creations came for him in the end, led by a headless surgeon.`},
{id:'alhazred',n:'Abdul Alhazred',c:'pp',ep:'The mad Arab',s:['nameless','hound','festival','dunwich'],l:['necronomicon','namelesscity'],
 d:`A poet of Sanaa in Yemen who wandered the ruins of Babylon and Memphis and lived ten years alone in the great southern desert. In Damascus around 730 he wrote Al Azif, the book later called the Necronomicon. According to Lovecraft's "History of the Necronomicon," an invisible monster seized and devoured him in broad daylight in 738.`},
{id:'wilbur',n:'Wilbur Whateley',c:'pp',ep:'The goatish boy of Dunwich',s:['dunwich'],l:['lavinia','oldwhateley','twin','yogsothoth','armitage','necronomicon','miskatonic','dunwich'],
 d:`Born on Candlemas 1913, Wilbur grew at a monstrous rate: walking at seven months, looking like a grown man by ten. He needed the complete Necronomicon to finish his grandfather's work. The Miskatonic library's watchdog killed him as he broke in to steal it, and below the waist he was not human.`},
{id:'lavinia',n:'Lavinia Whateley',c:'pp',ep:'Mother of the twins',s:['dunwich'],l:['wilbur','twin','oldwhateley','yogsothoth'],
 d:`A slightly deformed albino woman of thirty-five who read her father's books and roamed the hills in thunderstorms. She bore Wilbur, and his twin, without naming the father. She disappeared around Hallowe'en 1926.`},
{id:'oldwhateley',n:'Old Whateley',c:'pp',ep:'The wizard of Dunwich',s:['dunwich'],l:['wilbur','lavinia','twin','yogsothoth','shub','sentinelhill'],
 d:`Lavinia's father, a wizard Dunwich feared. He rebuilt the farmhouse for what was coming and taught Wilbur the rites. Dying in 1924, he told Wilbur to keep feeding the thing upstairs and to find the long chant on page 751 of the complete edition.`},
{id:'armitage',n:'Henry Armitage',c:'pp',ep:'Librarian of Miskatonic',s:['dunwich'],l:['wilbur','twin','necronomicon','miskatonic','sentinelhill'],
 d:`Head librarian of Miskatonic University, who refused to lend Wilbur the library's Latin Necronomicon. After Wilbur's death he decoded the boy's diary, and with Professors Rice and Morgan he climbed Sentinel Hill to destroy the twin with a powder and a counter-chant.`},
{id:'wilmarth',n:'Albert N. Wilmarth',c:'pp',ep:'The skeptical folklorist',s:['whisperer'],l:['akeley','migo','yuggoth','miskatonic','tsathoggua'],
 d:`A Miskatonic instructor of literature who writes skeptical rebuttals after the Vermont floods of 1927 wash strange bodies down the rivers. Henry Akeley's letters convince him. His visit to Akeley's farmhouse ends with a flight in the dark.`},
{id:'akeley',n:'Henry Wentworth Akeley',c:'pp',ep:'The besieged farmer',s:['whisperer'],l:['wilmarth','migo','shub','yuggoth','nyarlathotep'],
 d:`A scholarly recluse in the Vermont hills who records the Mi-Go's rites on a phonograph and holds them off with dogs and rifles. Then his letters turn calm and welcoming. When Wilmarth arrives, Akeley's brain is in a cylinder bound for Yuggoth, and the thing in his chair was wearing his face and hands.`},
{id:'dyer',n:'William Dyer',c:'pp',ep:'Leader of the Antarctic expedition',s:['mountains'],l:['danforth','lake','elderthings','shoggoths','antarctic','miskatonic','leng'],
 d:`The Miskatonic geologist who led the 1930–31 expedition. With Danforth he flew over the mountains and walked the dead city of the Elder Things. He writes his account to stop the Starkweather-Moore expedition from going back.`},
{id:'danforth',n:'Danforth',c:'pp',ep:'The one who looked back',s:['mountains'],l:['dyer','shoggoths','elderthings','necronomicon'],
 d:`A graduate student, widely read in forbidden books, who flew with Dyer. As they cleared the range he looked back at something beyond it and broke. He will only hint at what he saw, and sometimes cries out the shoggoths' word.`},
{id:'lake',n:'Professor Lake',c:'pp',ep:'The biologist',s:['mountains'],l:['elderthings','dyer'],
 d:`The expedition's biologist, who led a party northwest and dug up fourteen star-headed specimens from a cave. His radio reports grow more and more excited, and then stop. Dyer finds the camp torn apart.`},
{id:'olmstead',n:'The Innsmouth Narrator',c:'pp',ep:"Robert Olmstead, in Lovecraft's notes",s:['innsmouth'],l:['zadok','obed','deepones','innsmouth','yhanthlei','eod'],
 d:`A young man touring New England for his coming of age who stops in Innsmouth in 1927. After escaping the town at night he traces his family and finds Marsh blood. As the Innsmouth look comes on him, he resolves to free his cousin from the Canton asylum and swim out to Y'ha-nthlei.`,
 q:`and in that lair of the Deep Ones we shall dwell amidst wonder and glory for ever.`,qs:'innsmouth'},
{id:'zadok',n:'Zadok Allen',c:'pp',ep:'The old drunk who talked',s:['innsmouth'],l:['obed','deepones','hydra','olmstead','innsmouth'],
 d:`A ninety-six-year-old who told the narrator, in exchange for bootleg whiskey, how Obed Marsh brought the Deep Ones to Innsmouth and how the town died in 1846. Something out on the water ended the conversation, and he was not seen again.`},
{id:'obed',n:'Obed Marsh',c:'pp',ep:'Founder of the Esoteric Order',s:['innsmouth'],l:['deepones','dagon','eod','zadok','olmstead','innsmouth'],
 d:`An Innsmouth sea captain who learned the Deep Ones' bargain from Walakea, a South Sea chief, and brought it home. When the town resisted in 1846, the Deep Ones came up from the reef. His gold refinery and his descendants kept Innsmouth going.`},
{id:'peaslee',n:'Nathaniel Wingate Peaslee',c:'pp',ep:'The displaced professor',s:['shadowtime'],l:['yith','polyps','yithcity','miskatonic','pnakotic','kulten'],
 d:`A Miskatonic professor of political economy who collapsed in class on 14 May 1908 and spent five years as someone else. When his mind came back he dreamed of a vast library and an alien body. In 1935 he found the city in the Australian desert, and in its archive, a record in his own handwriting.`},
{id:'ward',n:'Charles Dexter Ward',c:'pp',ep:'The antiquarian heir',s:['cdw'],l:['curwen','willett','yogsothoth'],
 d:`A Providence youth obsessed with the past who discovered his ancestor Joseph Curwen, recovered his papers and raised him from his "essential Saltes." Curwen killed him and took his place, and the family committed the changed young man as insane.`},
{id:'curwen',n:'Joseph Curwen',c:'pp',ep:'The wizard of Pawtuxet',s:['cdw'],l:['ward','willett','yogsothoth'],
 d:`A Salem necromancer who fled to Providence in 1692 and stayed unnaturally young for decades while ships brought him bodies and screams came from his Pawtuxet farm. Townsmen raided it in 1771. Resurrected by his descendant, he murdered Ward and wore his identity, until Dr. Willett returned him to dust.`,
 q:`Doe not call up Any that you can not put downe.`,qs:'cdw'},
{id:'willett',n:'Marinus Bicknell Willett',c:'pp',ep:'The family physician',s:['cdw'],l:['ward','curwen'],
 d:`The Wards' doctor, who followed Charles's case to the Pawtuxet bungalow and went down into Curwen's catacombs. He realised who the man in the asylum really was, and used Curwen's own formula against him.`},
{id:'gilman',n:'Walter Gilman',c:'pp',ep:'The mathematics student',s:['witch'],l:['keziah','brownjenkin','nyarlathotep','azathoth','elderthings','arkham','miskatonic','eibon','kulten'],
 d:`A Miskatonic student from Haverhill who read the Necronomicon alongside non-Euclidean calculus and quantum physics, and rented Keziah Mason's old garret. Its angles let him dream his way into other dimensions, where Keziah, Brown Jenkin and the Black Man were waiting. He did not long survive Walpurgis Night.`},
{id:'keziah',n:'Keziah Mason',c:'pp',ep:'The witch of Arkham',s:['witch'],l:['brownjenkin','gilman','nyarlathotep','azathoth','arkham'],
 d:`An Arkham woman tried for witchcraft in 1692 who vanished from Salem gaol, leaving curves and angles drawn on the cell walls. She had learned how lines and angles lead out of space. In 1932 she was still at work.`},
{id:'pickman',n:'Richard Upton Pickman',c:'pp',ep:'The ghoul painter',s:['pickman','kadath'],l:['ghouls','carter'],
 d:`A Boston painter of horribly convincing ghouls, descended from a Salem woman hanged in 1692. His North End studio sat over old tunnels. His friend Thurber took a photograph off one canvas, and later looked at it. In the Dream-Quest, Pickman has become a ghoul himself and helps Carter.`,
 q:`it was a photograph from life.`,qs:'pickman'},
{id:'zann',n:'Erich Zann',c:'pp',ep:'The mute violist',s:['zann'],l:[],
 d:`A mute old German violist in a cheap theatre orchestra who lived at the top of a house on the Rue d'Auseil. At night he played wild music at the one window that looked out over the slope, keeping something out. The narrator found him still playing after he had died, and has never found the street again.`},
{id:'blake',n:'Robert Harrison Blake',c:'pp',ep:'The writer on College Hill',s:['haunter'],l:['trapezohedron','starrywisdom','nyarlathotep','azathoth','yogsothoth','eibon','kulten'],
 d:`A young Milwaukee writer of weird fiction who took rooms in Providence and grew fascinated by a black church on Federal Hill. Inside he found the Shining Trapezohedron and woke the thing that cannot bear light. He was found dead at his window in August 1935, after a storm knocked out the city's power. Lovecraft wrote the story for Robert Bloch.`},
{id:'derby',n:'Edward Pickman Derby',c:'pp',ep:'The poet',s:['doorstep'],l:['asenath','upton','shoggoths','innsmouth','miskatonic'],
 d:`A sheltered child prodigy and decadent poet who married Asenath Waite. She began taking over his body for longer and longer stretches. He killed her and buried her in the cellar, and she took him over from the grave.`},
{id:'asenath',n:'Asenath Waite',c:'pp',ep:'Ephraim Waite, in his daughter',s:['doorstep'],l:['derby','upton','innsmouth','deepones'],
 d:`A hypnotic, bulging-eyed Innsmouth girl who studied magic at Miskatonic and married Edward Derby. She was really her father, the wizard Ephraim Waite, who had exchanged bodies with her before "dying" mad. Then he wanted Derby's body.`},
{id:'upton',n:'Daniel Upton',c:'pp',ep:'The narrator who fired six shots',s:['doorstep'],l:['derby','asenath','arkham'],
 d:`An Arkham architect and Derby's oldest friend. A small, rotting thing in Derby's coat delivered a note to his door, and Upton went to the Arkham Sanitarium and shot the man in Edward's body.`,
 q:`It is true that I have sent six bullets through the head of my best friend`,qs:'doorstep'},
{id:'nahum',n:'Nahum Gardner',c:'pp',ep:'Farmer of the blasted heath',s:['colour'],l:['colour','ammi','blastedheath'],
 d:`The farmer west of Arkham whose land caught the meteorite. Over a year he watched his crops, stock, wife and sons fail one by one. When Ammi Pierce found him at the end, he was crumbling away.`},
{id:'ammi',n:'Ammi Pierce',c:'pp',ep:'The neighbour who remembers',s:['colour'],l:['nahum','colour','blastedheath'],
 d:`Nahum's old neighbour, the only one who kept visiting the farm. Decades later he tells the surveyor what happened, and he won't drink from the new reservoir.`},
{id:'delapore',n:'Delapore',c:'pp',ep:'Last of the de la Poers',s:['rats'],l:['exham'],
 d:`An American who restored his family's ancestral seat in 1923. His cats heard rats swarming in the walls. He led an expedition beneath the priory into a vast grotto where his ancestors had kept human cattle, and was found in the dark crouched over the half-eaten body of Captain Norrys, gibbering in older tongues.`},
{id:'jermyn',n:'Arthur Jermyn',c:'pp',ep:'Heir of the Jermyns',s:['jermyn'],l:[],
 d:`Descendant of the explorer Sir Wade Jermyn, in a family strange in body and mind for generations. When a box arrived from the Congo holding the remains of Wade's mysterious wife, Arthur saw what she had been, doused himself in oil and set himself alight.`},
{id:'kuranes',n:'Kuranes',c:'pp',ep:'King of Celephaïs',s:['celephais','kadath'],l:['celephais','carter'],
 d:`A London dreamer who found Celephaïs in childhood dreams and spent his life trying to return. His waking body died a tramp's death; his dreaming self reigns in Celephaïs. In the Dream-Quest, homesick, he has built a copy of a Cornish manor and advises Carter.`},
{id:'barzai',n:'Barzai the Wise',c:'pp',ep:'Who climbed Hatheg-Kla',s:['othergods'],l:['atal','greatones','pnakotic','ulthar'],
 d:`A sage steeped in the Pnakotic Manuscripts who climbed Hatheg-Kla to see the gods of Earth dancing. He found the Other Gods guarding them and was pulled screaming into the sky. A vast carved symbol was found where he had stood.`},
{id:'atal',n:'Atal',c:'pp',ep:'Patriarch of Ulthar',s:['ulthar','othergods','kadath'],l:['barzai','cats','carter','ulthar','greatones'],
 d:`As an innkeeper's boy he saw the caravan of Menes and the cats' revenge. As a young man he climbed Hatheg-Kla with Barzai and came down alone. Three hundred years old in the Dream-Quest, he gives Carter wine and advice in the temple of the Elder Ones.`},
{id:'rogers',n:'George Rogers',c:'pp',ep:'Proprietor of the waxworks',s:['museum'],l:['rhantegoth','yogsothoth'],
 d:`A former Madame Tussaud's sculptor who opened a horror museum in Southwark. He claimed to have brought Rhan-Tegoth back from Alaska. When Stephen Jones's night in the museum went wrong, Rogers ended up as one of his own exhibits.`},
{id:'zamacona',n:'Pánfilo de Zamacona',c:'pp',ep:'The conquistador underground',s:['mound'],l:['kenyan','tsathoggua','yig'],
 d:`A Spanish gentleman from Coronado's expedition of 1541 who followed a guide into the underground world of K'n-yan. He lived there for years, fled with a woman named T'la-yub, and left his manuscript inside the Oklahoma mound.`},
{id:'tyog',n:"T'yog",c:'pp',ep:'High priest of Shub-Niggurath',s:['aeons'],l:['ghatanothoa','shub'],
 d:`A priest of Mu who wrote a protective scroll with Shub-Niggurath's help and climbed Yaddith-Gho to challenge Ghatanothoa. The god's priests had replaced his scroll with a fake. Turned to stone with his brain still alive, he ended up as a mummy in Boston's Cabot Museum.`},
{id:'outsider',n:'The Outsider',c:'pp',ep:'The nameless narrator',s:['outsider'],l:['ghouls'],
 d:`A being raised alone in a dark, crumbling castle. He climbed the tower toward the light and walked into a party, where the guests fled screaming. Reaching for the monster in a gilded frame, he touched glass. Now he rides the night-wind with the ghouls.`,
 q:`I know always that I am an outsider; a stranger in this century and among those who are still men.`,qs:'outsider'},

/* Cults */
{id:'cthulhucult',n:'The Cthulhu Cult',c:'cu',ep:'Worldwide and undying',s:['coc'],l:['cthulhu','castro','legrasse','angell','johansen'],
 d:`A cult that waits for the stars to come right, reaching from the Greenland tribe Professor Webb encountered to Legrasse's swamp worshippers and the crew of the Alert. Old Castro says its deathless leaders live in the mountains of China.`,
 q:`Iä! Iä! Cthulhu fhtagn!`,qs:'coc'},
{id:'eod',n:'Esoteric Order of Dagon',c:'cu',ep:'The church of Innsmouth',s:['innsmouth'],l:['obed','dagon','hydra','deepones','innsmouth','zadok','olmstead'],
 d:`The faith Obed Marsh brought back from the South Seas, which took over Innsmouth's old Masonic Hall. Its oaths bind members to Dagon and the Deep Ones. Federal agents broke it up in 1928.`},
{id:'starrywisdom',n:'Church of Starry Wisdom',c:'cu',ep:'The sect on Federal Hill',s:['haunter'],l:['trapezohedron','blake','nyarlathotep'],
 d:`Founded in 1844 by Professor Enoch Bowen after he brought the Shining Trapezohedron back from Egypt, the sect met in a black stone church on Federal Hill in Providence. Disappearances followed it until it was suppressed in 1877. The steeple stayed sealed until Robert Blake went in.`},

/* Places */
{id:'rlyeh',n:"R'lyeh",c:'pl',dw:'919.9',ep:'47°9′ S, 126°43′ W',s:['coc','innsmouth'],l:['cthulhu','starspawn','johansen','cthulhucult'],
 d:`Cthulhu's tomb-city, built by his spawn and sunk under the South Pacific. Its geometry is wrong: one sailor was swallowed by an angle of masonry that was acute but behaved as if it were obtuse. It rose for a few days in 1925.`},
{id:'yhanthlei',n:"Y'ha-nthlei",c:'pl',dw:'919.9',ep:'The city beyond Devil Reef',s:['innsmouth'],l:['deepones','dagon','hydra','olmstead','innsmouth'],
 d:`The Deep Ones' cyclopean, many-columned city in the abyss beyond Devil Reef, off Innsmouth. Federal submarines torpedoed the deeps in 1928, but the city survived.`},
{id:'arkham',n:'Arkham',c:'pl',ep:'The witch-haunted town',s:['west','unnamable','silverkey','colour','dunwich','whisperer','mountains','innsmouth','witch','doorstep','shadowtime'],l:['miskatonic','keziah','gilman','west','carter','upton','kingsport','innsmouth','dunwich','brownjenkin'],
 d:`A fictional town on the Miskatonic River in Massachusetts, crowded with gambrel roofs, old burying-grounds and witch-trial history. Home to Miskatonic University, the Witch House, the Arkham Sanitarium and many of Lovecraft's narrators.`},
{id:'miskatonic',n:'Miskatonic University',c:'pl',ep:"Arkham's university",s:['west','dunwich','whisperer','mountains','witch','doorstep','shadowtime'],l:['armitage','wilmarth','dyer','lake','peaslee','west','gilman','asenath','necronomicon','arkham','colour'],
 d:`Its library keeps one of the few complete Necronomicons under lock. Its faculty keep running into the Mythos: Armitage, Wilmarth, Dyer, Lake, Peaslee. Its students include Herbert West, Walter Gilman and Asenath Waite.`},
{id:'innsmouth',n:'Innsmouth',c:'pl',ep:'The shadowed port',s:['innsmouth','doorstep'],l:['deepones','obed','zadok','eod','yhanthlei','asenath','olmstead'],
 d:`A decayed seaport near Arkham, sagging and half-deserted, with a gold refinery, a reek of fish and the Order's hall. Many of its people have the "Innsmouth look." Federal agents raided it in the winter of 1927–28 and dynamited rows of waterfront houses.`},
{id:'dunwich',n:'Dunwich',c:'pl',ep:'The decadent hill town',s:['dunwich'],l:['wilbur','twin','sentinelhill','oldwhateley'],
 d:`A decaying village in the upper Miskatonic valley, ringed by rounded hills crowned with stone circles. The whippoorwills there are said to wait outside a dying man's window to catch his soul.`},
{id:'kingsport',n:'Kingsport',c:'pl',ep:'The ancient seaport',s:['festival','strangehouse'],l:['nodens','arkham'],
 d:`A fog-wrapped colonial seaport near Arkham with steep lanes and a churchyard on Central Hill. At Yuletide its old families go down beneath the church. On Kingsport Head, the highest cliff, stands the strange high house in the mist.`},
{id:'blastedheath',n:'The Blasted Heath',c:'pl',ep:'Five acres of grey dust',s:['colour'],l:['colour','nahum','ammi'],
 d:`What was Nahum Gardner's farm, west of Arkham: five acres of fine grey dust where nothing grows. The new reservoir will cover it.`},
{id:'sentinelhill',n:'Sentinel Hill',c:'pl',ep:'Altar of the Whateleys',s:['dunwich'],l:['oldwhateley','twin','armitage','wilbur','dunwich'],
 d:`The highest hill near Dunwich, crowned with a table-like stone and scattered bones. The Whateleys held rites there on May Eve and Hallowe'en, and Armitage destroyed the twin there.`},
{id:'exham',n:'Exham Priory',c:'pl',dw:'914.2',ep:'Seat of the de la Poers',s:['rats'],l:['delapore'],
 d:`A priory near Anchester in England, built over a Druidic or older temple and a Roman shrine to Cybele. Beneath it lies the twilit grotto where generations of de la Poers kept and ate human livestock.`},
{id:'yuggoth',n:'Yuggoth',c:'pl',dw:'919.9',ep:'Pluto',s:['whisperer','haunter','museum','aeons'],l:['migo','akeley','rhantegoth','ghatanothoa','trapezohedron'],
 d:`A world at the edge of the solar system, identified with Pluto when it was discovered in 1930. Its black rivers of pitch and windowless towers house the Mi-Go's outpost; Rhan-Tegoth and Ghatanothoa came from there, and so did the Shining Trapezohedron.`},
{id:'leng',n:'Plateau of Leng',c:'pl',dw:'919.9',ep:'The cold plateau',s:['hound','kadath','mountains'],l:['lengmen','shantaks','moonbeasts','carter','antarctic'],
 d:`A cold, forbidden plateau that might be in Central Asia, in the Dreamlands, or both. The jade amulet in "The Hound" came from its corpse-eating cult. Its stone villages house the horned men, and a monastery holds the High Priest Not to Be Described. Dyer wonders whether the Antarctic plateau is Leng.`},
{id:'kadath',n:'Unknown Kadath',c:'pl',dw:'154.63',ep:'In the cold waste',s:['othergods','kadath'],l:['greatones','nyarlathotep','carter','leng','azathoth'],
 d:`The highest mountain of the Dreamlands, hidden in the cold waste beyond Leng, where the gods of Earth live in an onyx castle at the summit. Few dreamers have found it, and Nyarlathotep waits for those who do.`},
{id:'ulthar',n:'Ulthar',c:'pl',dw:'154.63',ep:'Beyond the river Skai',s:['ulthar','othergods','kadath'],l:['cats','atal','barzai','pnakotic','carter'],
 d:`A peaceful Dreamlands town where no one may kill a cat, home to old Atal and the temple of the Elder Ones.`},
{id:'celephais',n:'Celephaïs',c:'pl',dw:'154.63',ep:'City of Ooth-Nargai',s:['celephais','kadath'],l:['kuranes','carter'],
 d:`A marble city in the valley of Ooth-Nargai beside the Cerenerian Sea, where time doesn't pass. Kuranes dreamed it as a child and rules it as king.`},
{id:'sarnath',n:'Sarnath',c:'pl',dw:'154.63',ep:'In the land of Mnar',s:['sarnath'],l:['bokrug'],
 d:`A proud city of marble and gold built near the grey stone city of Ib. On the thousandth festival celebrating Ib's destruction it disappeared overnight; only the idol of Bokrug remained.`},
{id:'namelesscity',n:'The Nameless City',c:'pl',dw:'915.3',ep:'In the Arabian desert',s:['nameless'],l:['alhazred','necronomicon'],
 d:`A forgotten city half-buried in the Arabian sands, its rooms too low for a man to stand. Murals in a sloping tunnel show its reptilian builders, and they are not all dead. Abdul Alhazred dreamed of it the night before he wrote his couplet.`},
{id:'antarctic',n:'City of the Elder Things',c:'pl',dw:'919.89',ep:'Beyond the mountains of madness',s:['mountains'],l:['elderthings','shoggoths','dyer','danforth','lake','leng'],
 d:`A cyclopean stone city tens of millions of years old, spread across the plateau behind an Antarctic range higher than the Himalayas. Its carvings record the history of the Elder Things; its tunnels lead down to a black sea where shoggoths still live.`},
{id:'yithcity',n:'City of the Great Race',c:'pl',dw:'919.4',ep:'Under the Great Sandy Desert',s:['shadowtime'],l:['yith','polyps','peaslee'],
 d:`The Great Race's city in prehistoric Australia, built around an immense archive whose metal cases hold the histories written by every mind they borrowed. Its basalt blocks lie half-buried in the desert, where Peaslee went down into them in July 1935.`},

/* Tomes & artifacts */
{id:'necronomicon',n:'The Necronomicon',c:'tm',ep:'Al Azif, by Abdul Alhazred',s:['hound','festival','coc','cdw','dunwich','whisperer','mountains','witch','doorstep','shadowtime','haunter'],l:['alhazred','miskatonic','armitage','wilbur','yogsothoth','cthulhu','umr','danforth','namelesscity'],
 d:`Lovecraft's most famous invention. Written as Al Azif around 730, translated into Greek by Theodorus Philetas in 950 and into Latin by Olaus Wormius in 1228. Known copies sit in the British Museum, the Bibliothèque nationale, Harvard's Widener Library, the University of Buenos Aires and Miskatonic. Lovecraft quotes it but never gives its contents in full.`,
 q:`That is not dead which can eternal lie, / And with strange aeons even death may die.`,qs:'nameless'},
{id:'pnakotic',n:'The Pnakotic Manuscripts',c:'tm',ep:'Older than humanity',s:['polaris','othergods','kadath','shadowtime'],l:['yith','barzai','ulthar','peaslee'],
 d:`An ancient text from before mankind, known in Lomar and copied in the Dreamlands. Barzai knew it by heart. Peaslee's discoveries hint that its fragments reach back to the Great Race.`},
{id:'eibon',n:'The Book of Eibon',c:'tm',ep:'Borrowed from Clark Ashton Smith',s:['witch','haunter'],l:['gilman','blake','tsathoggua'],
 d:`Smith's grimoire of the Hyperborean wizard Eibon, which Lovecraft added to his own reading lists of forbidden books. Walter Gilman and Robert Blake both study it.`},
{id:'kulten',n:'Unaussprechlichen Kulten',c:'tm',ep:'By von Junzt; borrowed from Robert E. Howard',s:['witch','shadowtime','haunter'],l:['gilman','blake','peaslee'],
 d:`Friedrich von Junzt's "Nameless Cults," invented by Howard and given its German title by Lovecraft. Gilman, Peaslee and Blake all consult it.`},
{id:'trapezohedron',n:'The Shining Trapezohedron',c:'tm',ep:'A window on all space and time',s:['haunter'],l:['starrywisdom','blake','nyarlathotep','yuggoth'],
 d:`A nearly black, red-striated polyhedron suspended by seven supports in an asymmetric metal box. It was made on Yuggoth, treasured by the pharaoh Nephren-Ka, and brought to Providence by Enoch Bowen in 1844. Gazing into it summons the Haunter of the Dark, which cannot survive light.`},
{id:'silverkey',n:'The Silver Key',c:'tm',ep:"Carter's inheritance",s:['silverkey','gate'],l:['carter','umr','yogsothoth'],
 d:`A large, tarnished, arabesqued key in an ancestral box, with a parchment in an unknown tongue. It took Carter back to his boyhood and out of the waking world. In Through the Gates it unlocks the Ultimate Gate itself.`},
];

